INSERT INTO socialapp.t_comments
    (id, post_id, author_id, content, parent_id, created_at, updated_at) VALUES
    (200001, 100842, 9129, 'Cảm ơn bạn, đúng thứ mình đang cần. Bên mình cấu hình khác một chút nhưng ý tưởng thì giống hệt. (#0)', NULL, now() - INTERVAL '81 days', now() - INTERVAL '81 days'),
    (200002, 100843, 9157, 'Mình gặp y hệt tuần trước, cách này chạy được. Bên mình cấu hình khác một chút nhưng ý tưởng thì giống hệt. (#1)', NULL, now() - INTERVAL '189 days', now() - INTERVAL '189 days'),
    (200003, 100843, 9355, 'Cho mình hỏi thêm một chút: Bên mình cấu hình khác một chút nhưng ý tưởng thì giống hệt. (#2)', NULL, now() - INTERVAL '247 days', now() - INTERVAL '247 days'),
    (200004, 100844, 9005, 'Chỗ này mình nghĩ hơi khác: Cái bẫy là nó chỉ lộ ra khi chạy nhiều luồng cùng lúc. (#3)', NULL, now() - INTERVAL '289 days', now() - INTERVAL '289 days'),
    (200005, 100844, 9281, 'Đã thử và có kết quả tương tự. Cái bẫy là nó chỉ lộ ra khi chạy nhiều luồng cùng lúc. (#4)', NULL, now() - INTERVAL '203 days', now() - INTERVAL '203 days'),
    (200006, 100844, 9407, 'Bài viết rõ ràng, lưu lại đọc kỹ sau. Cái bẫy là nó chỉ lộ ra khi chạy nhiều luồng cùng lúc. (#5)', NULL, now() - INTERVAL '180 days', now() - INTERVAL '180 days'),
    (200007, 100844, 9129, 'Có ai đo trên bản mới chưa? Bạn có đo lại sau khi bật cache chưa? (#6)', NULL, now() - INTERVAL '15 days', now() - INTERVAL '15 days'),
    (200008, 100844, 9246, 'Mình từng làm ngược lại và hối hận. Bạn có đo lại sau khi bật cache chưa? (#7)', NULL, now() - INTERVAL '30 days', now() - INTERVAL '30 days'),
    (200009, 100844, 9416, 'Điểm thứ hai đáng giá nhất với mình. Bạn có đo lại sau khi bật cache chưa? (#8)', NULL, now() - INTERVAL '169 days', now() - INTERVAL '169 days'),
    (200010, 100845, 9259, 'Mình vừa đi qua đúng vấn đề này nên chép lại đầy đủ cho ai cần. Ban đầu tụi mình nghĩ nút thắt nằm ở tầng cơ sở dữ liệu, nên đổ công đi đánh thêm index và viết lại vài câu truy vấn. Kết quả gần như không nhúc nhích. Sau đó mới bật đo thật ở tầng ứng dụng thì phát hiện phần lớn thời gian trôi vào việc dựng lại cùng một tập dữ liệu nhiều lần trong một request, chứ không phải ở chỗ đọc đĩa. Sửa lại thành gom một lần rồi truyền xuống thì thời gian phản hồi rơi ngay xuống một phần mười, mà không cần thêm bất kỳ index nào. Bài học của mình là đo trước khi đoán, và đo ở đúng tầng đang nghi ngờ chứ không phải ở tầng dễ đo nhất.', NULL, now() - INTERVAL '176 days', now() - INTERVAL '176 days'),
    (200011, 102256, 9274, 'Bổ sung một chi tiết nhỏ: Chỗ này tài liệu chính thức viết hơi mơ hồ nên dễ hiểu nhầm. (#9)', NULL, now() - INTERVAL '150 days', now() - INTERVAL '150 days'),
