    (208992, 100257, 9018, 'Cho mình hỏi thêm một chút: Nếu dữ liệu nhỏ thì không thấy khác biệt gì đâu. (#8990)', NULL, now() - INTERVAL '280 days', now() - INTERVAL '280 days'),
    (208993, 100529, 9141, 'Chỗ này mình nghĩ hơi khác: Đáng để viết thành một bài riêng đấy bạn. (#8991)', NULL, now() - INTERVAL '99 days', now() - INTERVAL '99 days'),
    (208994, 100901, 9496, 'Đã thử và có kết quả tương tự. Đáng để viết thành một bài riêng đấy bạn. (#8992)', NULL, now() - INTERVAL '42 days', now() - INTERVAL '42 days'),
    (208995, 102524, 9075, 'Bài viết rõ ràng, lưu lại đọc kỹ sau. Đáng để viết thành một bài riêng đấy bạn. (#8993)', NULL, now() - INTERVAL '281 days', now() - INTERVAL '281 days'),
    (208996, 101417, 9276, 'Có ai đo trên bản mới chưa? Cách này có nhược điểm là khó quay lui khi cần. (#8994)', NULL, now() - INTERVAL '181 days', now() - INTERVAL '181 days'),
    (208997, 100748, 9392, 'Mình từng làm ngược lại và hối hận. Cách này có nhược điểm là khó quay lui khi cần. (#8995)', NULL, now() - INTERVAL '227 days', now() - INTERVAL '227 days'),
    (208998, 100419, 9009, 'Điểm thứ hai đáng giá nhất với mình. Cách này có nhược điểm là khó quay lui khi cần. (#8996)', NULL, now() - INTERVAL '231 days', now() - INTERVAL '231 days'),
    (208999, 102122, 9134, 'Bổ sung một chi tiết nhỏ: Mình sẽ thử vào cuối tuần rồi báo lại kết quả. (#8997)', 201521, now() - INTERVAL '237 days', now() - INTERVAL '237 days'),
    (209000, 100519, 9468, 'Không đồng ý lắm, nhưng hiểu vì sao bạn chọn vậy. Mình sẽ thử vào cuối tuần rồi báo lại kết quả. (#8998)', NULL, now() - INTERVAL '124 days', now() - INTERVAL '124 days'),
    (209001, 100846, 9382, 'Gửi giúp mình qua ho.tro@elitenexus.test nhé, dấu @ ở đây là email chứ không nhắc ai cả.', NULL, now() - INTERVAL '96 days', now() - INTERVAL '96 days');
